arguments.file_text:
namespace sv_3872aae4cce746d187f24216fab7666e;

public record Product(int Id, string Name, decimal Price, string Category, double Rating, bool InStock, string ImageUrl);
public record ProductFilter(List<string>? Categories, decimal? MinPrice, decimal? MaxPrice, bool InStockOnly);
public record PagedResult<T>(List<T> Items, int TotalCount, int Page, int PageSize);

public interface IProductService
{
    Task<PagedResult<Product>> SearchAsync(ProductFilter filter, string sortBy, int page, int pageSize);
    Task<List<string>> GetCategoriesAsync();
}

.catalog-layout {
    display: flex;
    gap: 1.5rem;
    padding: 1.5rem;
}

.catalog-sidebar {
    flex: 0 0 25%;
    max-width: 25%;
}

.catalog-main {
    flex: 1;
    min-width: 0;
}

/* Filters */
.catalog-filters h3 {
    margin-top: 0;
}

.filter-section {
    margin-bottom: 1.25rem;
}

.filter-section h4 {
    margin-bottom: 0.5rem;
}

.filter-checkbox {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    margin-bottom: 0.25rem;
    cursor: pointer;
}

.price-inputs label {
    display: block;
    margin-bottom: 0.5rem;
}

.price-inputs input {
    width: 100%;
    padding: 0.3rem 0.5rem;
    box-sizing: border-box;
}

.filter-actions {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}

.btn-apply, .btn-clear {
    padding: 0.5rem 1rem;
    cursor: pointer;
    border: 1px solid #ccc;
    border-radius: 4px;
}

.btn-apply {
    background-color: #0d6efd;
    color: white;
    border-color: #0d6efd;
}

.btn-clear {
    background-color: #f8f9fa;
}

/* Toolbar */
.catalog-toolbar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 1rem;
    padding: 0.5rem 0;
    border-bottom: 1px solid #eee;
}

.sort-control {
    display: flex;
    align-items: center;
    gap: 0.5rem;
}

.sort-control select {
    padding: 0.3rem 0.5rem;
}

.results-info {
    color: #666;
    font-size: 0.9rem;
}

/* Product Grid */
.product-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
    gap: 1.25rem;
}

.product-card {
    border: 1px solid #e0e0e0;
    border-radius: 8px;
    overflow: hidden;
    cursor: pointer;
    transition: box-shadow 0.2s;
}

.product-card:hover {
    box-shadow: 0 2px 12px rgba(0, 0, 0, 0.12);
}

.product-image {
    background: #f5f5f5;
    height: 160px;
    display: flex;
    align-items: center;
    justify-content: center;
    overflow: hidden;
}

.product-image img {
    max-width: 100%;
    max-height: 100%;
    object-fit: contain;
}

.product-info {
    padding: 0.75rem;
}

.product-name {
    margin: 0 0 0.25rem;
    font-size: 1rem;
}

.product-price {
    margin: 0 0 0.25rem;
    font-weight: bold;
    color: #2e7d32;
}

.product-rating {
    color: #f5a623;
    margin-bottom: 0.5rem;
}

.badge-out-of-stock {
    display: inline-block;
    background: #dc3545;
    color: white;
    font-size: 0.75rem;
    padding: 0.15rem 0.5rem;
    border-radius: 4px;
    margin-bottom: 0.5rem;
}

.btn-add-to-cart {
    width: 100%;
    padding: 0.5rem;
    background: #0d6efd;
    color: white;
    border: none;
    border-radius: 4px;
    cursor: pointer;
}

.btn-add-to-cart:disabled {
    background: #ccc;
    cursor: not-allowed;
}

/* Pagination */
.catalog-pagination {
    display: flex;
    justify-content: center;
    align-items: center;
    gap: 0.35rem;
    margin-top: 1.5rem;
    padding: 1rem 0;
}

.btn-page {
    padding: 0.4rem 0.75rem;
    border: 1px solid #ddd;
    border-radius: 4px;
    background: white;
    cursor: pointer;
}

.btn-page.active {
    background: #0d6efd;
    color: white;
    border-color: #0d6efd;
}

.btn-page:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

/* States */
.loading-state, .error-state, .empty-results {
    text-align: center;
    padding: 3rem 1rem;
    color: #666;
}

.error-state {
    color: #dc3545;
}

.error-state button {
    margin-top: 0.5rem;
    padding: 0.5rem 1rem;
    cursor: pointer;
}

